package com.campusplacement.repository; import com.campusplacement.model.Application; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ApplicationRepository extends JpaRepository<Application,UUID>{List<Application> findByStudentIdOrderByAppliedAtDesc(UUID id); boolean existsByStudentIdAndJobId(UUID studentId,String jobId); Optional<Application> findByIdAndStudentId(UUID id,UUID studentId);}
